export default [
  {"id": "js-01-1", "lang": "javascript", "level": 1, "title": "Salam dünya", "keywords": ["salam dünya", "hello world", "merhaba dünya", "привет мир", "console.log", "ilk proqram", "ilk kod", "first program", "первая программа", "ekrana yaz"], "code": "// İlk JavaScript proqramı: konsola yazı çıxarır\nconsole.log(\"Salam, dünya!\");\nconsole.log(\"JavaScript öyrənməyə xoş gəldin!\");\n"},
  {"id": "js-01-2", "lang": "javascript", "level": 1, "title": "let və const dəyişənləri", "keywords": ["dəyişən", "deyisen", "değişken", "variable", "переменная", "let", "const", "var", "dəyişənlər", "variables", "переменные"], "code": "// let dəyişə bilər, const dəyişmir\nconst ad = \"Aysel\";\nlet yas = 17;\nconst boy = 1.65;\nconst telebedir = true;\n\nconsole.log(\"Ad:\", ad);\nconsole.log(\"Yaş:\", yas);\nconsole.log(\"Boy:\", boy);\nconsole.log(\"Tələbədir:\", telebedir);\n\nyas = yas + 1; // let ilə dəyər dəyişir\nconsole.log(\"Gələn il yaş:\", yas);\n"},
  {"id": "js-01-3", "lang": "javascript", "level": 1, "title": "Template literal ilə mətn", "keywords": ["template literal", "şablon mətn", "string format", "formatlama", "yazı birləşdirmə", "şablon literalı", "шаблонная строка", "форматирование строк", "ad yaş", "backtick"], "code": "const ad = \"Elvin\";\nconst yas = 21;\nconst seher = \"Bakı\";\n\n// Tərs dırnaq içində ${} ilə dəyişən yerləşdirilir\nconsole.log(`Mənim adım ${ad}, yaşım ${yas}-dir.`);\nconsole.log(`${seher} şəhərində yaşayıram.`);\nconsole.log(`5 il sonra ${yas + 5} yaşında olacağam.`);\n"},
  {"id": "js-01-4", "lang": "javascript", "level": 1, "title": "Riyazi əməllər", "keywords": ["riyazi əməllər", "riyaziyyat", "toplama", "çıxma", "vurma", "bölmə", "math operators", "arithmetic", "hesab əməlləri", "арифметика", "операции", "toplama çıxma"], "code": "const a = 17;\nconst b = 5;\n\nconsole.log(\"Toplama:\", a + b);\nconsole.log(\"Çıxma:\", a - b);\nconsole.log(\"Vurma:\", a * b);\nconsole.log(\"Bölmə:\", a / b);\nconsole.log(\"Qalıq:\", a % b);\nconsole.log(\"Qüvvət:\", a ** 2);\nconsole.log(\"Tam hissə:\", Math.floor(a / b));\n"},
  {"id": "js-01-5", "lang": "javascript", "level": 1, "title": "Mətnlərlə ilk addımlar", "keywords": ["mətn", "string", "sətir", "uzunluq", "length", "touppercase", "birləşdirmə", "строки", "строка", "text basics", "mətn əməliyyatları"], "code": "const soz = \"Azərbaycan\";\n\nconsole.log(soz.length);              // uzunluq\nconsole.log(soz.toUpperCase());       // böyük hərflər\nconsole.log(soz.toLowerCase());       // kiçik hərflər\nconsole.log(soz[0]);                  // ilk hərf\nconsole.log(soz.slice(0, 4));         // ilk 4 hərf\nconsole.log(soz + \" gözəl ölkədir\");  // birləşdirmə\nconsole.log(soz.repeat(2));           // təkrar\n"},
  {"id": "js-02-1", "lang": "javascript", "level": 2, "title": "typeof ilə tiplər", "keywords": ["tip", "type", "typeof", "data types", "məlumat tipləri", "tipler", "типы данных", "number string boolean", "tip yoxla"], "code": "console.log(typeof 42);\nconsole.log(typeof 3.14);\nconsole.log(typeof \"salam\");\nconsole.log(typeof true);\nconsole.log(typeof undefined);\nconsole.log(typeof null);        // tarixi səhv: \"object\"\nconsole.log(typeof [1, 2, 3]);   // massiv də object-dir\nconsole.log(typeof { a: 1 });\nconsole.log(typeof function () {});\n"},
  {"id": "js-02-2", "lang": "javascript", "level": 2, "title": "Tip çevirmə", "keywords": ["tip çevirmə", "type conversion", "parseint", "parsefloat", "number", "string", "çevirmə", "преобразование типов", "cast", "rəqəmə çevir"], "code": "console.log(Number(\"42\") + 8);\nconsole.log(parseInt(\"15px\"));\nconsole.log(parseFloat(\"3.75 metr\"));\nconsole.log(String(123) + \"4\");\nconsole.log(Number(\"salam\"));         // NaN\nconsole.log(Boolean(\"\"), Boolean(\"a\"), Boolean(0), Boolean(5));\nconsole.log(Number.isNaN(Number(\"x\")));\n"},
  {"id": "js-02-3", "lang": "javascript", "level": 2, "title": "if / else şərti", "keywords": ["if else", "şərt", "condition", "şərt operatoru", "koşul", "условие", "if", "else if", "yaş yoxla", "şərtlər"], "code": "const yas = 20;\n\nif (yas < 13) {\n  console.log(\"Uşaq\");\n} else if (yas < 18) {\n  console.log(\"Yeniyetmə\");\n} else if (yas < 65) {\n  console.log(\"Böyük\");\n} else {\n  console.log(\"Yaşlı\");\n}\n"},
  {"id": "js-02-4", "lang": "javascript", "level": 2, "title": "Müqayisə və məntiq operatorları", "keywords": ["müqayisə", "məntiq", "comparison", "logical", "===", "&&", "||", "!", "karşılaştırma", "сравнение", "логические операторы", "bərabərlik"], "code": "console.log(5 === 5, 5 === \"5\", 5 == \"5\");\nconsole.log(10 > 3, 10 <= 3, 10 !== 4);\n\nconst yas = 25;\nconst telebe = true;\nconsole.log(yas > 18 && telebe);\nconsole.log(yas > 30 || telebe);\nconsole.log(!telebe);\n"},
  {"id": "js-02-5", "lang": "javascript", "level": 2, "title": "Üçlü operator və ?? ilə default dəyər", "keywords": ["üçlü operator", "ternary", "nullish", "??", "?.", "optional chaining", "default dəyər", "kısa koşul", "тернарный оператор"], "code": "const bal = 72;\nconsole.log(bal >= 50 ? \"Keçdi\" : \"Kəsildi\");\n\nconst ad = null;\nconsole.log(ad ?? \"Adsız\");             // null/undefined olanda default\nconsole.log(0 ?? 10, 0 || 10);          // ?? yalnız null/undefined sayır\n\nconst user = { profil: { sehir: \"Gəncə\" } };\nconsole.log(user.profil?.sehir);\nconsole.log(user.aile?.say);            // xəta vermir, undefined\n"},
  {"id": "js-03-1", "lang": "javascript", "level": 3, "title": "for dövrü ilə say", "keywords": ["for", "dövr", "loop", "say", "saymaq", "1 den 10 a", "1-10", "цикл for", "döngü", "for dövrü", "count"], "code": "for (let i = 1; i <= 10; i++) {\n  console.log(\"Say:\", i);\n}\n"},
  {"id": "js-03-2", "lang": "javascript", "level": 3, "title": "Vurma cədvəli", "keywords": ["vurma cədvəli", "multiplication table", "çarpım tablosu", "таблица умножения", "cədvəl", "for iç-içə", "nested loop"], "code": "const n = 7;\nfor (let i = 1; i <= 10; i++) {\n  console.log(`${n} x ${i} = ${n * i}`);\n}\n"},
  {"id": "js-03-3", "lang": "javascript", "level": 3, "title": "while dövrü", "keywords": ["while", "dövr", "loop", "şərtli dövr", "while loop", "цикл while", "döngü", "do while", "yarıya böl"], "code": "let say = 1;\nwhile (say <= 5) {\n  console.log(\"while:\", say);\n  say++;\n}\n\nlet eded = 100;\nlet addim = 0;\ndo {\n  eded = eded / 2;\n  addim++;\n} while (eded > 1);\nconsole.log(\"100-ü 1-dən kiçik edənə qədər bölmə addımı:\", addim);\n"},
  {"id": "js-03-4", "lang": "javascript", "level": 3, "title": "break, continue və cüt ədədlər", "keywords": ["break", "continue", "cüt ədədlər", "even numbers", "çift sayılar", "четные числа", "dövrü dayandır", "atla"], "code": "for (let i = 1; i <= 20; i++) {\n  if (i % 2 !== 0) continue;   // təkləri atla\n  if (i > 14) break;           // 14-dən sonra dayan\n  console.log(i);\n}\n"},
  {"id": "js-03-5", "lang": "javascript", "level": 3, "title": "Ədədlərin cəmi və ortası", "keywords": ["cəm", "ortalama", "sum", "average", "toplam", "сумма", "среднее", "1 den 100", "cəm hesabla"], "code": "let cem = 0;\nfor (let i = 1; i <= 100; i++) cem += i;\nconsole.log(\"1-dən 100-ə qədər cəm:\", cem);\nconsole.log(\"Orta:\", cem / 100);\n\nconst qiymetler = [80, 95, 70, 100];\nlet toplam = 0;\nfor (const q of qiymetler) toplam += q;\nconsole.log(\"Qiymət ortası:\", toplam / qiymetler.length);\n"},
  {"id": "js-04-1", "lang": "javascript", "level": 4, "title": "Massiv əsasları", "keywords": ["massiv", "array", "siyahı", "list", "dizi", "массив", "push", "pop", "length", "siyahı əməliyyatları", "array basics"], "code": "const meyveler = [\"alma\", \"armud\", \"nar\"];\n\nmeyveler.push(\"üzüm\");        // sona əlavə\nmeyveler.unshift(\"heyva\");    // əvvələ əlavə\nconsole.log(meyveler);\nconsole.log(meyveler.length);\nconsole.log(meyveler.pop());  // sondakını çıxar\nconsole.log(meyveler.shift()); // əvvəldəkini çıxar\nconsole.log(meyveler.indexOf(\"armud\"), meyveler.includes(\"nar\"));\n"},
  {"id": "js-04-2", "lang": "javascript", "level": 4, "title": "map, filter, forEach", "keywords": ["map", "filter", "foreach", "massiv metodları", "array methods", "dəyişdir", "süz", "фильтр", "map filter", "высший порядок"], "code": "const ededler = [1, 2, 3, 4, 5, 6];\n\nconst kvadrat = ededler.map((x) => x * x);\nconst cutler = ededler.filter((x) => x % 2 === 0);\nconsole.log(kvadrat);\nconsole.log(cutler);\n\nededler.forEach((x, i) => console.log(`${i}: ${x}`));\n"},
  {"id": "js-04-3", "lang": "javascript", "level": 4, "title": "reduce, find, some, every", "keywords": ["reduce", "find", "some", "every", "cəm", "toplam", "массив методы", "array reduce", "axtar", "tap"], "code": "const qiymetler = [12, 45, 7, 88, 31];\n\nconsole.log(qiymetler.reduce((a, b) => a + b, 0));\nconsole.log(qiymetler.find((x) => x > 40));\nconsole.log(qiymetler.findIndex((x) => x === 7));\nconsole.log(qiymetler.some((x) => x > 80));\nconsole.log(qiymetler.every((x) => x > 5));\nconsole.log(Math.max(...qiymetler), Math.min(...qiymetler));\n"},
  {"id": "js-04-4", "lang": "javascript", "level": 4, "title": "slice, splice, spread", "keywords": ["slice", "splice", "spread", "kopyala", "concat", "birləşdir", "copy array", "массив копия", "массив срез"], "code": "const a = [1, 2, 3, 4, 5];\nconst b = [...a, 6, 7];      // spread ilə kopya\nconsole.log(a.slice(1, 4));  // [2,3,4] a dəyişmir\nconsole.log(b);\n\nconst c = [10, 20, 30, 40];\nc.splice(1, 2, 99);          // 1-ci indeksdən 2 elementi 99 ilə əvəz et\nconsole.log(c);\nconsole.log(a.concat([8, 9]).reverse());\n"},
  {"id": "js-04-5", "lang": "javascript", "level": 4, "title": "Sıralama və tərs çevirmə", "keywords": ["sıralama", "sort", "reverse", "sırala", "sıralamak", "сортировка", "ən böyük", "ən kiçik", "sort numbers"], "code": "const ededler = [40, 100, 1, 5, 25];\n\n// sort() standartda mətn kimi sıralayır, ona görə müqayisə lazımdır\nconsole.log([...ededler].sort());\nconsole.log([...ededler].sort((a, b) => a - b));\nconsole.log([...ededler].sort((a, b) => b - a));\n\nconst adlar = [\"Zaur\", \"Aysel\", \"Murad\", \"Leyla\"];\nconsole.log(adlar.sort((a, b) => a.localeCompare(b, \"az\")));\n"},
  {"id": "js-05-1", "lang": "javascript", "level": 5, "title": "Faktorial", "keywords": ["faktorial", "factorial", "n!", "факториал", "hesablama", "dövrlə faktorial", "faktoriyel"], "code": "function faktorial(n) {\n  let netice = 1;\n  for (let i = 2; i <= n; i++) netice *= i;\n  return netice;\n}\n\nfor (let n = 0; n <= 10; n++) {\n  console.log(`${n}! = ${faktorial(n)}`);\n}\n"},
  {"id": "js-05-2", "lang": "javascript", "level": 5, "title": "Fibonaççi ardıcıllığı", "keywords": ["fibonacci", "fibonaççi", "fibonaci", "fibonacci sequence", "ardıcıllıq", "фибоначчи", "ardicilliq"], "code": "const say = 15;\nconst fib = [0, 1];\nfor (let i = 2; i < say; i++) {\n  fib.push(fib[i - 1] + fib[i - 2]);\n}\nconsole.log(fib.join(\", \"));\n"},
  {"id": "js-05-3", "lang": "javascript", "level": 5, "title": "Sadə ədəd yoxlaması", "keywords": ["sadə ədəd", "prime", "asal sayı", "asal sayilar", "простое число", "prime number", "sadə ədədlər"], "code": "function sadeDir(n) {\n  if (n < 2) return false;\n  for (let i = 2; i * i <= n; i++) {\n    if (n % i === 0) return false;\n  }\n  return true;\n}\n\nconst siyahi = [];\nfor (let n = 1; n <= 50; n++) if (sadeDir(n)) siyahi.push(n);\nconsole.log(\"50-yə qədər sadə ədədlər:\", siyahi.join(\" \"));\n"},
  {"id": "js-05-4", "lang": "javascript", "level": 5, "title": "ƏBOB və ƏKOB", "keywords": ["əbob", "əkob", "gcd", "lcm", "ebob", "ekok", "нод", "нок", "ən böyük ortaq bölən", "euclid"], "code": "function ebob(a, b) {\n  while (b !== 0) {\n    [a, b] = [b, a % b];\n  }\n  return a;\n}\nconst ekob = (a, b) => (a / ebob(a, b)) * b;\n\nconsole.log(\"ƏBOB(48, 18) =\", ebob(48, 18));\nconsole.log(\"ƏKOB(12, 18) =\", ekob(12, 18));\n"},
  {"id": "js-05-5", "lang": "javascript", "level": 5, "title": "Rəqəmlər cəmi və Armstrong ədədi", "keywords": ["rəqəmlər cəmi", "digit sum", "armstrong", "rəqəm", "цифры числа", "ədəd rəqəmləri", "rakam toplamı"], "code": "function reqemCemi(n) {\n  return String(n).split(\"\").reduce((c, r) => c + Number(r), 0);\n}\nconsole.log(\"12345 rəqəmləri cəmi:\", reqemCemi(12345));\n\nfunction armstrongMu(n) {\n  const r = String(n).split(\"\");\n  return r.reduce((c, x) => c + Number(x) ** r.length, 0) === n;\n}\nconst tapilan = [];\nfor (let n = 100; n < 1000; n++) if (armstrongMu(n)) tapilan.push(n);\nconsole.log(\"Armstrong ədədləri:\", tapilan.join(\", \"));\n"},
  {"id": "js-06-1", "lang": "javascript", "level": 6, "title": "Funksiyalar və return", "keywords": ["funksiya", "function", "return", "qaytar", "funksiyalar", "функция", "fonksiyon", "parametr", "argument", "funksiya yaz"], "code": "function salamla(ad, soyad = \"\") {\n  return `Salam, ${ad} ${soyad}`.trim();\n}\n\nfunction kvadrat(x) {\n  return x * x;\n}\n\nconsole.log(salamla(\"Aysel\"));\nconsole.log(salamla(\"Elvin\", \"Məmmədov\"));\nconsole.log(kvadrat(9));\n"},
  {"id": "js-06-2", "lang": "javascript", "level": 6, "title": "Ox funksiyaları (arrow)", "keywords": ["arrow function", "ox funksiyası", "=>", "ok fonksiyonu", "стрелочная функция", "lambda", "qısa funksiya", "anonim funksiya"], "code": "const topla = (a, b) => a + b;\nconst ikiqat = (x) => x * 2;\nconst salam = () => \"Salam!\";\n\nconsole.log(topla(3, 4));\nconsole.log(ikiqat(21));\nconsole.log(salam());\n\nconsole.log([1, 2, 3].map((x) => x * 10));\nconsole.log([5, 12, 8, 130].filter((x) => x > 10));\n"},
  {"id": "js-06-3", "lang": "javascript", "level": 6, "title": "Rest parametrləri və arguments", "keywords": ["rest", "...args", "çox parametr", "dəyişən sayda arqument", "rest parameters", "неограниченное число аргументов", "spread", "sınırsız parametre"], "code": "function cem(...ededler) {\n  return ededler.reduce((a, b) => a + b, 0);\n}\n\nfunction melumat(ad, ...hobbiler) {\n  return `${ad}: ${hobbiler.length} hobbi (${hobbiler.join(\", \")})`;\n}\n\nconsole.log(cem(1, 2, 3));\nconsole.log(cem(10, 20, 30, 40));\nconsole.log(melumat(\"Leyla\", \"kitab\", \"şahmat\", \"üzgüçülük\"));\nconsole.log(Math.max(...[3, 9, 4]));\n"},
  {"id": "js-06-4", "lang": "javascript", "level": 6, "title": "Callback və yüksək dərəcəli funksiyalar", "keywords": ["callback", "higher order function", "geri çağırma", "yüksək dərəcəli funksiya", "функция высшего порядка", "колбэк", "funksiya parametri"], "code": "function tekrarla(say, emel) {\n  for (let i = 1; i <= say; i++) emel(i);\n}\n\ntekrarla(3, (n) => console.log(\"Addım\", n));\n\nfunction emeliyyat(a, b, f) {\n  return f(a, b);\n}\nconsole.log(emeliyyat(6, 3, (x, y) => x * y));\nconsole.log(emeliyyat(6, 3, (x, y) => x - y));\n"},
  {"id": "js-06-5", "lang": "javascript", "level": 6, "title": "Destructuring və default", "keywords": ["destructuring", "parçalama", "dağıtma", "деструктуризация", "obyekt parçala", "massiv parçala", "default parametr"], "code": "const [a, b, ...qalan] = [10, 20, 30, 40];\nconsole.log(a, b, qalan);\n\nconst { ad, yas = 18, unvan: ev } = { ad: \"Murad\", unvan: \"Bakı\" };\nconsole.log(ad, yas, ev);\n\nfunction salamla({ ad, soyad = \"?\" }) {\n  return `${ad} ${soyad}`;\n}\nconsole.log(salamla({ ad: \"Nigar\" }));\n\nlet x = 1, y = 2;\n[x, y] = [y, x];\nconsole.log(x, y);\n"},
  {"id": "js-07-1", "lang": "javascript", "level": 7, "title": "Palindrom yoxlaması", "keywords": ["palindrom", "palindrome", "tərsi ilə eyni", "ters düz aynı", "палиндром", "mətn tərsi", "sözü tərsinə çevir"], "code": "function palindromdur(metn) {\n  const t = metn.toLowerCase().replace(/[^a-zəıöüçşğ0-9]/g, \"\");\n  return t === [...t].reverse().join(\"\");\n}\n\nconsole.log(palindromdur(\"level\"));\nconsole.log(palindromdur(\"Ana\"));\nconsole.log(palindromdur(\"A man, a plan, a canal: Panama\"));\nconsole.log(palindromdur(\"salam\"));\n"},
  {"id": "js-07-2", "lang": "javascript", "level": 7, "title": "Sözləri və hərfləri saymaq", "keywords": ["söz say", "hərf say", "word count", "harf sayısı", "подсчет слов", "say", "saymaq", "tezlik", "frequency", "mətn analizi"], "code": "const metn = \"bu gün hava çox gözəldir və bu gün dərs var\";\nconst sozler = metn.split(\" \");\nconsole.log(\"Söz sayı:\", sozler.length);\n\nconst say = {};\nfor (const s of sozler) say[s] = (say[s] || 0) + 1;\nconsole.log(say);\n\nconst sait = [...\"aeıioöuüə\"];\nconst saitSayi = [...metn].filter((h) => sait.includes(h)).length;\nconsole.log(\"Sait sayı:\", saitSayi);\n"},
  {"id": "js-07-3", "lang": "javascript", "level": 7, "title": "Sezar şifrələməsi", "keywords": ["sezar", "caesar cipher", "şifrələmə", "şifre", "шифр цезаря", "encrypt", "decrypt", "şifrələ", "kriptoqrafiya"], "code": "function sezar(metn, addim) {\n  return [...metn].map((h) => {\n    if (!/[a-z]/i.test(h)) return h;\n    const baza = h === h.toUpperCase() ? 65 : 97;\n    return String.fromCharCode(((h.charCodeAt(0) - baza + addim + 26) % 26) + baza);\n  }).join(\"\");\n}\n\nconst sifreli = sezar(\"Hello World\", 3);\nconsole.log(sifreli);\nconsole.log(sezar(sifreli, -3));\n"},
  {"id": "js-07-4", "lang": "javascript", "level": 7, "title": "Mətni başlıq formatına salmaq", "keywords": ["başlıq", "title case", "capitalize", "ilk hərf böyük", "baş hərf", "заглавные буквы", "camelcase", "kebab", "slug"], "code": "function basliq(metn) {\n  return metn.split(\" \").map((s) => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase()).join(\" \");\n}\nfunction camel(metn) {\n  return metn.toLowerCase().replace(/[- _]+(.)/g, (_, h) => h.toUpperCase());\n}\nfunction slug(metn) {\n  return metn.toLowerCase().trim().replace(/[^a-z0-9]+/g, \"-\").replace(/^-|-$/g, \"\");\n}\n\nconsole.log(basliq(\"nibras kod sayti\"));\nconsole.log(camel(\"istifadeci adi sahesi\"));\nconsole.log(slug(\"  Hello, JavaScript World!  \"));\n"},
  {"id": "js-07-5", "lang": "javascript", "level": 7, "title": "Anaqram yoxlaması", "keywords": ["anaqram", "anagram", "hərflər eyni", "harfleri aynı", "анаграмма", "söz oyunu", "sozleri qrupla"], "code": "const normallas = (s) => [...s.toLowerCase()].sort().join(\"\");\nconst anaqramdir = (a, b) => normallas(a) === normallas(b);\n\nconsole.log(anaqramdir(\"listen\", \"silent\"));\nconsole.log(anaqramdir(\"kitab\", \"bakit\"));\nconsole.log(anaqramdir(\"salam\", \"malas\"));\nconsole.log(anaqramdir(\"python\", \"javascript\"));\n\nconst qruplar = {};\nfor (const s of [\"tea\", \"eat\", \"ate\", \"tan\", \"nat\", \"bat\"]) {\n  (qruplar[normallas(s)] ||= []).push(s);\n}\nconsole.log(Object.values(qruplar));\n"},
  {"id": "js-08-1", "lang": "javascript", "level": 8, "title": "Obyektlər", "keywords": ["obyekt", "object", "key value", "açar dəyər", "nesne", "объект", "xassə", "property", "obyekt yaz", "object basics"], "code": "const telebe = {\n  ad: \"Aysel\",\n  yas: 17,\n  fenler: [\"riyaziyyat\", \"fizika\"],\n  salamla() {\n    return `Salam, mən ${this.ad}`;\n  },\n};\n\nconsole.log(telebe.ad, telebe[\"yas\"]);\ntelebe.sinif = 11;              // yeni xassə\ndelete telebe.yas;              // silmək\nconsole.log(telebe.salamla());\nconsole.log(Object.keys(telebe));\nconsole.log(Object.entries(telebe).length);\n"},
  {"id": "js-08-2", "lang": "javascript", "level": 8, "title": "Object.entries və dövr", "keywords": ["object.entries", "object.keys", "object.values", "for in", "obyekt dövrü", "object loop", "obyekt üzərində dövr", "перебор объекта"], "code": "const qiymetler = { riyaziyyat: 90, fizika: 75, kimya: 82 };\n\nfor (const [fenn, bal] of Object.entries(qiymetler)) {\n  console.log(`${fenn}: ${bal}`);\n}\nconst ortalama = Object.values(qiymetler).reduce((a, b) => a + b, 0) / Object.keys(qiymetler).length;\nconsole.log(\"Orta bal:\", ortalama.toFixed(1));\n\nconst artirilmis = Object.fromEntries(Object.entries(qiymetler).map(([k, v]) => [k, v + 5]));\nconsole.log(artirilmis);\n"},
  {"id": "js-08-3", "lang": "javascript", "level": 8, "title": "Map və Set", "keywords": ["map", "set", "çoxluq", "unikal elementlər", "unique", "harita", "словарь", "множество", "təkrarsız", "duplikat sil"], "code": "const tekrar = [3, 1, 3, 2, 1, 5, 2];\nconst unikal = [...new Set(tekrar)];\nconsole.log(unikal);\n\nconst xerite = new Map();\nxerite.set(\"Bakı\", 2300000);\nxerite.set(\"Gəncə\", 335000);\nxerite.set(\"Sumqayıt\", 345000);\nconsole.log(xerite.get(\"Gəncə\"), xerite.has(\"Şəki\"), xerite.size);\nfor (const [sher, say] of xerite) console.log(sher, say);\n"},
  {"id": "js-08-4", "lang": "javascript", "level": 8, "title": "Obyekt kopyalama və birləşdirmə", "keywords": ["spread obyekt", "object.assign", "structuredclone", "kopyala", "deep copy", "derin kopya", "копия объекта", "birləşdir", "merge"], "code": "const baza = { ad: \"Elvin\", ayarlar: { tema: \"tünd\", dil: \"az\" } };\n\nconst sig = { ...baza, yas: 20 };                  // üstdən kopya\nconst derin = structuredClone(baza);               // dərin kopya\nderin.ayarlar.tema = \"açıq\";\n\nconsole.log(sig);\nconsole.log(baza.ayarlar.tema, derin.ayarlar.tema);\nconsole.log(Object.assign({}, { a: 1 }, { b: 2 }, { a: 3 }));\n"},
  {"id": "js-08-5", "lang": "javascript", "level": 8, "title": "Telefon kitabçası", "keywords": ["telefon kitabçası", "phone book", "kontaktlar", "contacts", "rehber", "телефонная книга", "əlaqələr", "axtarış obyekt"], "code": "const kitabca = new Map();\n\nfunction elaveEt(ad, nomre) {\n  kitabca.set(ad.toLowerCase(), nomre);\n}\nfunction axtar(ad) {\n  return kitabca.get(ad.toLowerCase()) ?? \"Tapılmadı\";\n}\n\nelaveEt(\"Aysel\", \"050-111-22-33\");\nelaveEt(\"Murad\", \"055-444-55-66\");\nconsole.log(axtar(\"aysel\"));\nconsole.log(axtar(\"Zaur\"));\nconsole.log([...kitabca.keys()].sort());\n"},
  {"id": "js-09-1", "lang": "javascript", "level": 9, "title": "JSON ilə işləmək", "keywords": ["json", "json.stringify", "json.parse", "json çevir", "serialize", "сериализация", "json oxu", "json yaz", "obyekti mətnə çevir"], "code": "const telebe = { ad: \"Nigar\", yas: 19, fenler: [\"tarix\", \"coğrafiya\"], aktiv: true };\n\nconst metn = JSON.stringify(telebe);\nconsole.log(metn);\nconsole.log(JSON.stringify(telebe, null, 2));\n\nconst geri = JSON.parse(metn);\nconsole.log(geri.ad, geri.fenler.length);\n\ntry {\n  JSON.parse(\"{pozulmuş json}\");\n} catch (e) {\n  console.log(\"JSON səhvdir:\", e.name);\n}\n"},
  {"id": "js-09-2", "lang": "javascript", "level": 9, "title": "Math funksiyaları və təsadüfi ədəd", "keywords": ["math", "təsadüfi", "random", "riyaziyyat", "floor", "ceil", "round", "sqrt", "случайное число", "rastgele", "math.random"], "code": "console.log(Math.round(4.6), Math.floor(4.9), Math.ceil(4.1), Math.trunc(-4.9));\nconsole.log(Math.sqrt(144), Math.pow(2, 10), Math.abs(-7));\nconsole.log(Math.max(4, 9, 2), Math.min(4, 9, 2));\nconsole.log(Math.PI.toFixed(4));\n\nfunction aralik(min, max) {\n  return Math.floor(Math.random() * (max - min + 1)) + min;\n}\nconst t = aralik(1, 6);\nconsole.log(\"1-6 arası təsadüfi ədəd düzgündür:\", t >= 1 && t <= 6);\n"},
  {"id": "js-09-3", "lang": "javascript", "level": 9, "title": "Tarix və vaxt", "keywords": ["tarix", "date", "vaxt", "time", "gün", "ay", "il", "date", "tarih", "дата", "tarix fərqi", "gün sayı"], "code": "const d = new Date(2026, 9, 3);   // aylar 0-dan başlayır: 9 = oktyabr\nconsole.log(d.getFullYear(), d.getMonth() + 1, d.getDate());\nconsole.log(d.getDay());          // 0 = bazar\n\nconst bitis = new Date(2026, 11, 31);\nconst ferq = Math.round((bitis - d) / (1000 * 60 * 60 * 24));\nconsole.log(\"İlin sonuna qalan gün:\", ferq);\n\nd.setDate(d.getDate() + 30);\nconsole.log(d.toISOString().slice(0, 10));\n"},
  {"id": "js-09-4", "lang": "javascript", "level": 9, "title": "Regex ilə yoxlama", "keywords": ["regex", "regular expression", "müntəzəm ifadə", "düzənli ifade", "регулярное выражение", "e-poçt yoxla", "telefon yoxla", "test", "match", "replace"], "code": "const emailRe = /^[\\w.+-]+@[\\w-]+\\.[\\w.]+$/;\nconsole.log(emailRe.test(\"nibrascode@gmail.com\"));\nconsole.log(emailRe.test(\"yanlis@\"));\n\nconst metn = \"Telefon: 050-123-45-67 və 055-765-43-21\";\nconsole.log(metn.match(/\\d{3}-\\d{3}-\\d{2}-\\d{2}/g));\nconsole.log(metn.replace(/\\d/g, \"#\"));\n\nconst tarix = \"2026-10-03\".match(/(\\d{4})-(\\d{2})-(\\d{2})/);\nconsole.log(tarix[1], tarix[2], tarix[3]);\n"},
  {"id": "js-09-5", "lang": "javascript", "level": 9, "title": "Ədəd formatı və Intl", "keywords": ["intl", "tolocalestring", "format", "pul formatı", "ədəd formatı", "para birimi", "форматирование чисел", "tofixed", "valyuta", "number format"], "code": "const mebleg = 1234567.891;\n\nconsole.log(mebleg.toFixed(2));\nconsole.log(mebleg.toLocaleString(\"en-US\"));\nconsole.log(new Intl.NumberFormat(\"en-US\", { style: \"currency\", currency: \"USD\" }).format(mebleg));\nconsole.log((0.256).toLocaleString(\"en-US\", { style: \"percent\", maximumFractionDigits: 1 }));\nconsole.log((255).toString(2), (255).toString(16).toUpperCase());\nconsole.log(parseInt(\"ff\", 16), 0.1 + 0.2);\n"},
  {"id": "js-10-1", "lang": "javascript", "level": 10, "title": "try / catch / finally", "keywords": ["try catch", "xəta idarəsi", "error handling", "exception", "hata yakalama", "обработка ошибок", "finally", "throw", "istisna"], "code": "function bol(a, b) {\n  if (b === 0) throw new Error(\"Sıfıra bölmək olmaz\");\n  return a / b;\n}\n\ntry {\n  console.log(bol(10, 2));\n  console.log(bol(5, 0));\n} catch (xeta) {\n  console.log(\"Xəta:\", xeta.message);\n} finally {\n  console.log(\"Hesablama bitdi\");\n}\n"},
  {"id": "js-10-2", "lang": "javascript", "level": 10, "title": "Öz xəta sinifi", "keywords": ["öz xəta", "custom error", "error class", "özel hata", "свое исключение", "extends error", "xəta sinfi", "doğrulama xətası"], "code": "class DogrulamaXetasi extends Error {\n  constructor(sahe, mesaj) {\n    super(mesaj);\n    this.name = \"DogrulamaXetasi\";\n    this.sahe = sahe;\n  }\n}\n\nfunction yoxla(istifadeci) {\n  if (!istifadeci.ad) throw new DogrulamaXetasi(\"ad\", \"Ad boş ola bilməz\");\n  if (istifadeci.yas < 0) throw new DogrulamaXetasi(\"yas\", \"Yaş mənfi ola bilməz\");\n  return \"Düzgündür\";\n}\n\nfor (const u of [{ ad: \"Aysel\", yas: 20 }, { ad: \"\", yas: 5 }, { ad: \"Zaur\", yas: -1 }]) {\n  try {\n    console.log(yoxla(u));\n  } catch (e) {\n    console.log(`${e.name} [${e.sahe}]: ${e.message}`);\n  }\n}\n"},
  {"id": "js-10-3", "lang": "javascript", "level": 10, "title": "Təhlükəsiz bölmə və yoxlama", "keywords": ["təhlükəsiz", "safe parse", "input validation", "doğrulama", "validasiya", "проверка ввода", "nan yoxla", "ədəd yoxla", "isfinite"], "code": "function tehlukesizCevir(metn) {\n  const n = Number(metn);\n  if (metn === \"\" || Number.isNaN(n)) return { ok: false, sebeb: \"ədəd deyil\" };\n  if (!Number.isFinite(n)) return { ok: false, sebeb: \"sonsuzdur\" };\n  return { ok: true, deyer: n };\n}\n\nfor (const t of [\"42\", \"3.5\", \"salam\", \"\", \"1e999\"]) {\n  console.log(JSON.stringify(t), \"=>\", tehlukesizCevir(t));\n}\n"},
  {"id": "js-10-4", "lang": "javascript", "level": 10, "title": "assert ilə sadə testlər", "keywords": ["assert", "test", "sınaq", "unit test", "yoxlama", "тест", "console.assert", "mini test", "test yaz"], "code": "function ok(ad, ferz) {\n  console.log((ferz ? \"KEÇDİ \" : \"SƏHV  \") + ad);\n}\nconst cem = (a, b) => a + b;\nconst maks = (arr) => Math.max(...arr);\n\nok(\"cem(2,3) = 5\", cem(2, 3) === 5);\nok(\"cem(-1,1) = 0\", cem(-1, 1) === 0);\nok(\"maks([4,9,2]) = 9\", maks([4, 9, 2]) === 9);\nok(\"maks([]) = -Infinity\", maks([]) === -Infinity);\n"},
  {"id": "js-10-5", "lang": "javascript", "level": 10, "title": "Promise xətaları və catch zənciri", "keywords": ["promise.catch", "async error", "rejected", "xəta ardıcıllığı", "finally", "promise reject", "промис ошибка", "catch zənciri"], "code": "function yoxla(n) {\n  return new Promise((hell, redd) => {\n    setTimeout(() => (n > 0 ? hell(n * 2) : redd(new Error(\"Mənfi ədəd: \" + n))), 10);\n  });\n}\n\nyoxla(5)\n  .then((x) => {\n    console.log(\"Nəticə:\", x);\n    return yoxla(-3);\n  })\n  .then(() => console.log(\"Bura çatmır\"))\n  .catch((e) => console.log(\"Tutuldu:\", e.message))\n  .finally(() => console.log(\"Bitdi\"));\n"},
  {"id": "js-11-1", "lang": "javascript", "level": 11, "title": "Rekursiya: faktorial və fibonaççi", "keywords": ["rekursiya", "recursion", "özünü çağıran funksiya", "рекурсия", "özü çağıran", "rekürsif", "faktorial rekursiya", "fibonacci rekursiya"], "code": "function faktorial(n) {\n  if (n <= 1) return 1;\n  return n * faktorial(n - 1);\n}\n\nconst yaddas = new Map();\nfunction fib(n) {\n  if (n < 2) return n;\n  if (yaddas.has(n)) return yaddas.get(n);\n  const r = fib(n - 1) + fib(n - 2);\n  yaddas.set(n, r);\n  return r;\n}\n\nconsole.log(faktorial(10));\nconsole.log(fib(30), fib(50));\n"},
  {"id": "js-11-2", "lang": "javascript", "level": 11, "title": "Rekursiya: massiv və iç-içə siyahılar", "keywords": ["rekursiya massiv", "flatten", "düzləşdir", "iç-içə massiv", "nested array", "derinlik", "рекурсия массив", "cəm", "recursive sum"], "code": "function duzlestir(arr) {\n  const netice = [];\n  for (const el of arr) {\n    if (Array.isArray(el)) netice.push(...duzlestir(el));\n    else netice.push(el);\n  }\n  return netice;\n}\nfunction derin(arr) {\n  return 1 + Math.max(0, ...arr.filter(Array.isArray).map(derin));\n}\n\nconst yuva = [1, [2, [3, [4, 5]], 6], [[7]]];\nconsole.log(duzlestir(yuva));\nconsole.log(\"Dərinlik:\", derin(yuva));\nconsole.log(yuva.flat(Infinity).length);\n"},
  {"id": "js-11-3", "lang": "javascript", "level": 11, "title": "İkili axtarış", "keywords": ["ikili axtarış", "binary search", "ikili arama", "бинарный поиск", "axtarış alqoritmi", "search algorithm", "sıralı massiv"], "code": "function ikiliAxtaris(arr, hedef) {\n  let sol = 0, sag = arr.length - 1, addim = 0;\n  while (sol <= sag) {\n    addim++;\n    const orta = Math.floor((sol + sag) / 2);\n    if (arr[orta] === hedef) return { index: orta, addim };\n    if (arr[orta] < hedef) sol = orta + 1;\n    else sag = orta - 1;\n  }\n  return { index: -1, addim };\n}\n\nconst arr = Array.from({ length: 1000 }, (_, i) => i * 3);\nconsole.log(ikiliAxtaris(arr, 2100));\nconsole.log(ikiliAxtaris(arr, 2101));\n"},
  {"id": "js-11-4", "lang": "javascript", "level": 11, "title": "Bubble və selection sort", "keywords": ["bubble sort", "selection sort", "sıralama alqoritmi", "kabarcık sıralama", "пузырьковая сортировка", "sort algoritmi", "sıralama"], "code": "function bubble(arr) {\n  const a = [...arr];\n  for (let i = 0; i < a.length - 1; i++) {\n    for (let j = 0; j < a.length - 1 - i; j++) {\n      if (a[j] > a[j + 1]) [a[j], a[j + 1]] = [a[j + 1], a[j]];\n    }\n  }\n  return a;\n}\nfunction selection(arr) {\n  const a = [...arr];\n  for (let i = 0; i < a.length; i++) {\n    let m = i;\n    for (let j = i + 1; j < a.length; j++) if (a[j] < a[m]) m = j;\n    [a[i], a[m]] = [a[m], a[i]];\n  }\n  return a;\n}\n\nconst data = [64, 25, 12, 22, 11, 90, 5];\nconsole.log(bubble(data));\nconsole.log(selection(data));\n"},
  {"id": "js-11-5", "lang": "javascript", "level": 11, "title": "Merge sort və Quick sort", "keywords": ["merge sort", "quick sort", "sürətli sıralama", "birləşdirmə sıralaması", "быстрая сортировка", "сортировка слиянием", "divide and conquer"], "code": "function merge(sol, sag) {\n  const n = [];\n  while (sol.length && sag.length) n.push(sol[0] <= sag[0] ? sol.shift() : sag.shift());\n  return [...n, ...sol, ...sag];\n}\nfunction mergeSort(a) {\n  if (a.length < 2) return a;\n  const o = Math.floor(a.length / 2);\n  return merge(mergeSort(a.slice(0, o)), mergeSort(a.slice(o)));\n}\nfunction quickSort(a) {\n  if (a.length < 2) return a;\n  const [pivot, ...qalan] = a;\n  return [...quickSort(qalan.filter((x) => x < pivot)), pivot, ...quickSort(qalan.filter((x) => x >= pivot))];\n}\n\nconst data = [38, 27, 43, 3, 9, 82, 10];\nconsole.log(mergeSort(data));\nconsole.log(quickSort(data));\n"},
  {"id": "js-12-1", "lang": "javascript", "level": 12, "title": "Sinif (class)", "keywords": ["sinif", "class", "oop", "obyekt yönümlü", "constructor", "sınıf", "класс", "metod", "method", "class yaz"], "code": "class Telebe {\n  constructor(ad, yas) {\n    this.ad = ad;\n    this.yas = yas;\n    this.qiymetler = [];\n  }\n  qiymetEle(q) {\n    this.qiymetler.push(q);\n    return this;\n  }\n  ortalama() {\n    if (!this.qiymetler.length) return 0;\n    return this.qiymetler.reduce((a, b) => a + b, 0) / this.qiymetler.length;\n  }\n  toString() {\n    return `${this.ad} (${this.yas}) ortalama: ${this.ortalama().toFixed(1)}`;\n  }\n}\n\nconst t = new Telebe(\"Aysel\", 17).qiymetEle(90).qiymetEle(85).qiymetEle(100);\nconsole.log(String(t));\n"},
  {"id": "js-12-2", "lang": "javascript", "level": 12, "title": "Varislik: extends və super", "keywords": ["varislik", "inheritance", "extends", "super", "miras", "наследование", "ana sinif", "alt sinif", "polimorfizm", "polymorphism"], "code": "class Heyvan {\n  constructor(ad) {\n    this.ad = ad;\n  }\n  sesCixar() {\n    return `${this.ad} səs çıxarır`;\n  }\n}\nclass Pisik extends Heyvan {\n  sesCixar() {\n    return `${super.sesCixar()}: miyav`;\n  }\n}\nclass It extends Heyvan {\n  sesCixar() {\n    return `${this.ad}: hav-hav`;\n  }\n}\n\nfor (const h of [new Pisik(\"Mırmır\"), new It(\"Rex\"), new Heyvan(\"Naməlum\")]) {\n  console.log(h.sesCixar(), \"|\", h instanceof Heyvan);\n}\n"},
  {"id": "js-12-3", "lang": "javascript", "level": 12, "title": "Getter, setter və private sahələr", "keywords": ["getter", "setter", "private", "#", "gizli sahə", "encapsulation", "inkapsulyasiya", "свойство", "kapsülleme", "class field"], "code": "class Hesab {\n  #balans = 0;\n  constructor(sahib) {\n    this.sahib = sahib;\n  }\n  get balans() {\n    return this.#balans;\n  }\n  set balans(deyer) {\n    if (deyer < 0) throw new RangeError(\"Balans mənfi ola bilməz\");\n    this.#balans = deyer;\n  }\n}\n\nconst h = new Hesab(\"Elvin\");\nh.balans = 150;\nconsole.log(h.sahib, h.balans);\ntry {\n  h.balans = -5;\n} catch (e) {\n  console.log(e.name + \": \" + e.message);\n}\n"},
  {"id": "js-12-4", "lang": "javascript", "level": 12, "title": "Static metodlar və sayğac", "keywords": ["static", "statik metod", "class static", "sayğac", "counter", "статический метод", "sinif metodu", "id generator"], "code": "class Mehsul {\n  static say = 0;\n  static yeniId() {\n    return ++Mehsul.say;\n  }\n  constructor(ad, qiymet) {\n    this.id = Mehsul.yeniId();\n    this.ad = ad;\n    this.qiymet = qiymet;\n  }\n  static muqayise(a, b) {\n    return a.qiymet - b.qiymet;\n  }\n}\n\nconst siyahi = [new Mehsul(\"Kitab\", 12), new Mehsul(\"Qələm\", 2), new Mehsul(\"Dəftər\", 5)];\nconsole.log(siyahi.sort(Mehsul.muqayise).map((m) => `${m.id}:${m.ad}`));\nconsole.log(\"Cəmi məhsul:\", Mehsul.say);\n"},
  {"id": "js-12-5", "lang": "javascript", "level": 12, "title": "Fiqurlar və polimorfizm", "keywords": ["mixin", "abstract", "fiqur", "shape", "polimorfizm", "sahə", "perimetr", "фигуры", "geometrik fiqurlar", "area", "sinif iyerarxiyası"], "code": "class Fiqur {\n  sahe() { return 0; }\n  melumat() { return `${this.constructor.name}: sahə = ${this.sahe().toFixed(2)}`; }\n}\nclass Daire extends Fiqur {\n  constructor(r) { super(); this.r = r; }\n  sahe() { return Math.PI * this.r ** 2; }\n}\nclass Duzbucaq extends Fiqur {\n  constructor(en, uz) { super(); this.en = en; this.uz = uz; }\n  sahe() { return this.en * this.uz; }\n}\nclass Ucbucaq extends Fiqur {\n  constructor(a, h) { super(); this.a = a; this.h = h; }\n  sahe() { return (this.a * this.h) / 2; }\n}\n\n[new Daire(3), new Duzbucaq(4, 5), new Ucbucaq(6, 4)].forEach((f) => console.log(f.melumat()));\n"},
  {"id": "js-13-1", "lang": "javascript", "level": 13, "title": "reduce ilə qruplaşdırma", "keywords": ["groupby", "qruplaşdır", "reduce", "qrup", "group by", "группировка", "say", "tezlik", "sayma", "array reduce group"], "code": "const mehsullar = [\n  { ad: \"Alma\", kateqoriya: \"meyvə\", qiymet: 2 },\n  { ad: \"Süd\", kateqoriya: \"süd\", qiymet: 3 },\n  { ad: \"Armud\", kateqoriya: \"meyvə\", qiymet: 3 },\n  { ad: \"Pendir\", kateqoriya: \"süd\", qiymet: 8 },\n  { ad: \"Çörək\", kateqoriya: \"unlu\", qiymet: 1 },\n];\n\nconst qruplar = mehsullar.reduce((acc, m) => {\n  (acc[m.kateqoriya] ||= []).push(m.ad);\n  return acc;\n}, {});\nconsole.log(qruplar);\n\nconst cemler = mehsullar.reduce((acc, m) => ({ ...acc, [m.kateqoriya]: (acc[m.kateqoriya] || 0) + m.qiymet }), {});\nconsole.log(cemler);\n"},
  {"id": "js-13-2", "lang": "javascript", "level": 13, "title": "flat, flatMap, Array.from", "keywords": ["flat", "flatmap", "array.from", "aralıq", "range", "массив из", "düzləşdirmə", "array from", "zip"], "code": "const range = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);\nconsole.log(range(1, 10));\n\nconst cumleler = [\"salam dünya\", \"nibras kod\"];\nconsole.log(cumleler.flatMap((c) => c.split(\" \")));\nconsole.log([[1, 2], [3, [4]], 5].flat(2));\n\nconst a = [\"a\", \"b\", \"c\"], b = [1, 2, 3];\nconsole.log(a.map((x, i) => [x, b[i]]));\nconsole.log(Array.from(\"salam\"), Array(3).fill(0));\n"},
  {"id": "js-13-3", "lang": "javascript", "level": 13, "title": "Massiv statistikası", "keywords": ["statistika", "median", "orta", "moda", "variasiya", "statistics", "mean", "mode", "статистика", "ortalama", "standart sapma"], "code": "const data = [4, 8, 6, 5, 3, 8, 9, 8, 2];\n\nconst orta = data.reduce((a, b) => a + b, 0) / data.length;\nconst s = [...data].sort((a, b) => a - b);\nconst median = s.length % 2 ? s[(s.length - 1) / 2] : (s[s.length / 2 - 1] + s[s.length / 2]) / 2;\nconst say = new Map();\ndata.forEach((x) => say.set(x, (say.get(x) || 0) + 1));\nconst moda = [...say.entries()].sort((a, b) => b[1] - a[1])[0][0];\nconst sapma = Math.sqrt(data.reduce((a, x) => a + (x - orta) ** 2, 0) / data.length);\n\nconsole.log({ orta: +orta.toFixed(2), median, moda, sapma: +sapma.toFixed(2) });\n"},
  {"id": "js-13-4", "lang": "javascript", "level": 13, "title": "Siyahı üzərində zəncirvari əməliyyatlar", "keywords": ["metod zənciri", "method chaining", "pipeline", "map filter reduce", "цепочка методов", "zəncir", "data pipeline", "sifariş cəmi"], "code": "const sifarisler = [\n  { musteri: \"Aysel\", mebleg: 120, odenilib: true },\n  { musteri: \"Murad\", mebleg: 80, odenilib: false },\n  { musteri: \"Nigar\", mebleg: 200, odenilib: true },\n  { musteri: \"Zaur\", mebleg: 45, odenilib: true },\n];\n\nconst netice = sifarisler\n  .filter((s) => s.odenilib)\n  .map((s) => ({ ...s, vergi: s.mebleg * 0.18 }))\n  .sort((a, b) => b.mebleg - a.mebleg)\n  .map((s) => `${s.musteri}: ${s.mebleg} (vergi ${s.vergi.toFixed(1)})`);\n\nconsole.log(netice.join(\"\\n\"));\nconsole.log(\"Cəmi:\", sifarisler.filter((s) => s.odenilib).reduce((a, s) => a + s.mebleg, 0));\n"},
  {"id": "js-13-5", "lang": "javascript", "level": 13, "title": "Matris əməliyyatları", "keywords": ["matris", "matrix", "iki ölçülü massiv", "2d array", "transpoze", "çarpma", "матрица", "matris çarpımı", "transpose"], "code": "const A = [[1, 2, 3], [4, 5, 6]];\nconst B = [[7, 8], [9, 10], [11, 12]];\n\nconst transpoze = (m) => m[0].map((_, j) => m.map((s) => s[j]));\nconst vur = (x, y) => x.map((s) => transpoze(y).map((c) => s.reduce((t, v, i) => t + v * c[i], 0)));\n\nconsole.log(transpoze(A));\nconsole.log(vur(A, B));\nconsole.log(A.map((s) => s.join(\" \")).join(\"\\n\"));\n"},
  {"id": "js-14-1", "lang": "javascript", "level": 14, "title": "Generator funksiyaları", "keywords": ["generator", "function*", "yield", "generator funksiya", "генератор", "tənbəl hesablama", "lazy", "iterator", "yield nədir"], "code": "function* say(bas, son) {\n  for (let i = bas; i <= son; i++) yield i;\n}\nconsole.log([...say(1, 5)]);\n\nfunction* fibonacci() {\n  let [a, b] = [0, 1];\n  while (true) {\n    yield a;\n    [a, b] = [b, a + b];\n  }\n}\nconst ilk10 = [];\nfor (const x of fibonacci()) {\n  if (ilk10.length === 10) break;\n  ilk10.push(x);\n}\nconsole.log(ilk10);\n"},
  {"id": "js-14-2", "lang": "javascript", "level": 14, "title": "Öz iterator", "keywords": ["iterator", "symbol.iterator", "for of", "iterasiya", "итератор", "iterable", "öz iteratorumuz", "dövr obyekti", "custom iterator"], "code": "class Aralik {\n  constructor(bas, son, addim = 1) {\n    Object.assign(this, { bas, son, addim });\n  }\n  [Symbol.iterator]() {\n    let cari = this.bas;\n    const { son, addim } = this;\n    return {\n      next: () => (cari <= son ? { value: ((cari += addim) - addim), done: false } : { value: undefined, done: true }),\n    };\n  }\n}\n\nconsole.log([...new Aralik(1, 10, 3)]);\nfor (const x of new Aralik(5, 7)) console.log(\"x =\", x);\n"},
  {"id": "js-14-3", "lang": "javascript", "level": 14, "title": "Tənbəl ardıcıllıq: take, map, filter", "keywords": ["tənbəl", "lazy sequence", "take", "generator pipeline", "sonsuz ardıcıllıq", "ленивые вычисления", "infinite sequence", "pipeline generator"], "code": "function* natural() {\n  let n = 1;\n  while (true) yield n++;\n}\nfunction* xerite(it, f) { for (const x of it) yield f(x); }\nfunction* suz(it, f) { for (const x of it) if (f(x)) yield x; }\nfunction* gotur(it, n) {\n  let i = 0;\n  for (const x of it) {\n    if (i++ >= n) return;\n    yield x;\n  }\n}\n\nconst netice = gotur(xerite(suz(natural(), (x) => x % 3 === 0), (x) => x * x), 6);\nconsole.log([...netice]);\n"},
  {"id": "js-14-4", "lang": "javascript", "level": 14, "title": "Entries, keys və Symbol.asyncIterator", "keywords": ["entries", "keys", "values", "massiv iterator", "map iterator", "итераторы", "for of entries", "indeks və dəyər", "index value"], "code": "const meyveler = [\"alma\", \"armud\", \"nar\"];\nfor (const [i, m] of meyveler.entries()) console.log(i, m);\n\nconst xerite = new Map([[\"a\", 1], [\"b\", 2]]);\nconsole.log([...xerite.keys()], [...xerite.values()]);\n\nconst it = meyveler[Symbol.iterator]();\nconsole.log(it.next(), it.next(), it.next(), it.next());\n\nasync function* gec() {\n  for (let i = 1; i <= 3; i++) {\n    await new Promise((r) => setTimeout(r, 5));\n    yield i;\n  }\n}\n(async () => {\n  for await (const x of gec()) console.log(\"gec:\", x);\n})();\n"},
  {"id": "js-14-5", "lang": "javascript", "level": 14, "title": "Generator ilə id və sıra", "keywords": ["id generator", "sıra", "ardıcıl nömrə", "sequence id", "queue", "növbə", "генератор id", "nömrələyici", "counter generator"], "code": "function* idler(prefiks) {\n  let n = 1;\n  while (true) yield `${prefiks}-${String(n++).padStart(3, \"0\")}`;\n}\nconst sifarisId = idler(\"SF\");\nconsole.log(sifarisId.next().value, sifarisId.next().value, sifarisId.next().value);\n\nfunction* novbe(adlar) {\n  for (const ad of adlar) yield `${ad} növbədədir`;\n}\nconst n = novbe([\"Aysel\", \"Murad\"]);\nconsole.log(n.next(), n.next(), n.next());\n"},
  {"id": "js-15-1", "lang": "javascript", "level": 15, "title": "Closure (qapanma)", "keywords": ["closure", "qapanma", "sayğac", "counter", "lexical scope", "замыкание", "kapanış", "daxili funksiya", "gizli dəyişən"], "code": "function sayac(bas = 0) {\n  let say = bas;\n  return {\n    artir: () => ++say,\n    azalt: () => --say,\n    deyer: () => say,\n  };\n}\n\nconst a = sayac();\nconst b = sayac(100);\na.artir(); a.artir();\nb.azalt();\nconsole.log(a.deyer(), b.deyer());   // hər sayğacın öz dəyişəni var\n"},
  {"id": "js-15-2", "lang": "javascript", "level": 15, "title": "Currying və compose", "keywords": ["currying", "curry", "compose", "pipe", "funksiya kompozisiyası", "каррирование", "композиция функций", "funksional proqramlaşdırma", "functional"], "code": "const curry = (f) => function c(...a) {\n  return a.length >= f.length ? f(...a) : (...b) => c(...a, ...b);\n};\nconst compose = (...fns) => (x) => fns.reduceRight((v, f) => f(v), x);\nconst pipe = (...fns) => (x) => fns.reduce((v, f) => f(v), x);\n\nconst topla = curry((a, b, c) => a + b + c);\nconsole.log(topla(1)(2)(3), topla(1, 2)(3));\n\nconst ikiqat = (x) => x * 2;\nconst birArtir = (x) => x + 1;\nconsole.log(compose(ikiqat, birArtir)(5)); // (5+1)*2\nconsole.log(pipe(ikiqat, birArtir)(5));    // 5*2+1\n"},
  {"id": "js-15-3", "lang": "javascript", "level": 15, "title": "Memoize ilə keş", "keywords": ["memoize", "keş", "cache", "yaddaşa yaz", "мемоизация", "кэш", "performans", "sürətləndir", "hesablamanı yadda saxla"], "code": "function memoize(f) {\n  const kes = new Map();\n  return (...args) => {\n    const acar = JSON.stringify(args);\n    if (!kes.has(acar)) kes.set(acar, f(...args));\n    return kes.get(acar);\n  };\n}\n\nlet hesablama = 0;\nconst yavas = memoize((n) => {\n  hesablama++;\n  return n * n;\n});\nconsole.log(yavas(12), yavas(12), yavas(12), yavas(5));\nconsole.log(\"Faktiki hesablama sayı:\", hesablama);\n"},
  {"id": "js-15-4", "lang": "javascript", "level": 15, "title": "Debounce və once", "keywords": ["debounce", "once", "throttle", "bir dəfə", "bir kərə işlə", "функция один раз", "gecikdirmə", "taymer", "settimeout closure"], "code": "function once(f) {\n  let bitdi = false, netice;\n  return (...a) => (bitdi ? netice : ((bitdi = true), (netice = f(...a))));\n}\nconst baslat = once(() => {\n  console.log(\"Başladı (yalnız bir dəfə)\");\n  return 42;\n});\nconsole.log(baslat(), baslat());\n\nfunction debounce(f, ms) {\n  let t;\n  return (...a) => {\n    clearTimeout(t);\n    t = setTimeout(() => f(...a), ms);\n  };\n}\nconst yaz = debounce((x) => console.log(\"Son çağırış:\", x), 30);\nyaz(1); yaz(2); yaz(3);\n"},
  {"id": "js-15-5", "lang": "javascript", "level": 15, "title": "Modul nümunəsi: IIFE", "keywords": ["iife", "modul", "module pattern", "dərhal işləyən funksiya", "anında çağırılan funksiya", "модуль", "namespace", "gizli state", "singleton"], "code": "const Anbar = (function () {\n  const mallar = {};\n  return {\n    elave(ad, say) {\n      mallar[ad] = (mallar[ad] || 0) + say;\n    },\n    cixar(ad, say) {\n      if ((mallar[ad] || 0) < say) throw new Error(ad + \" çatmır\");\n      mallar[ad] -= say;\n    },\n    hamisi: () => ({ ...mallar }),\n  };\n})();\n\nAnbar.elave(\"kitab\", 10);\nAnbar.elave(\"qələm\", 25);\nAnbar.cixar(\"kitab\", 3);\nconsole.log(Anbar.hamisi());\ntry { Anbar.cixar(\"qələm\", 100); } catch (e) { console.log(e.message); }\n"},
  {"id": "js-16-1", "lang": "javascript", "level": 16, "title": "Symbol və WeakMap ilə gizli məlumat", "keywords": ["symbol", "weakmap", "gizli məlumat", "private data", "unikal açar", "символ", "benzersiz anahtar", "weakset", "metadata"], "code": "const gizli = Symbol(\"gizli\");\nconst user = { ad: \"Aysel\", [gizli]: \"parol-123\" };\nconsole.log(Object.keys(user), user[gizli]);\nconsole.log(JSON.stringify(user));\n\nconst meta = new WeakMap();\nfunction qeydEt(obj, data) { meta.set(obj, data); }\nconst a = {}, b = {};\nqeydEt(a, { ziyaret: 3 });\nconsole.log(meta.get(a), meta.get(b), meta.has(a));\n"},
  {"id": "js-16-2", "lang": "javascript", "level": 16, "title": "Proxy ilə yoxlama və izləmə", "keywords": ["proxy", "proxy", "reflect", "izləmə", "validation proxy", "прокси", "nəzarət", "get set trap", "reactive"], "code": "const yoxla = {\n  set(hedef, acar, deyer) {\n    if (acar === \"yas\" && (!Number.isInteger(deyer) || deyer < 0)) throw new TypeError(\"yas müsbət tam ədəd olmalıdır\");\n    console.log(`${acar} = ${deyer}`);\n    return Reflect.set(hedef, acar, deyer);\n  },\n  get(hedef, acar) {\n    return acar in hedef ? hedef[acar] : `(${String(acar)} yoxdur)`;\n  },\n};\nconst sexs = new Proxy({}, yoxla);\nsexs.ad = \"Elvin\";\nsexs.yas = 22;\nconsole.log(sexs.ad, sexs.sinif);\ntry { sexs.yas = -5; } catch (e) { console.log(e.message); }\n"},
  {"id": "js-16-3", "lang": "javascript", "level": 16, "title": "Optional chaining və dərin oxuma", "keywords": ["optional chaining", "dərin oxuma", "get path", "?.", "yol ilə oxu", "lodash get", "safe access", "iç-içə obyekt", "nested object"], "code": "function get(obj, yol, ilkin) {\n  const n = yol.split(\".\").reduce((o, k) => o?.[k], obj);\n  return n === undefined ? ilkin : n;\n}\nfunction set(obj, yol, deyer) {\n  const acarlar = yol.split(\".\");\n  const son = acarlar.pop();\n  const hedef = acarlar.reduce((o, k) => (o[k] ??= {}), obj);\n  hedef[son] = deyer;\n  return obj;\n}\n\nconst konfiq = { server: { port: 8080, dil: [\"az\", \"en\"] } };\nconsole.log(get(konfiq, \"server.port\"), get(konfiq, \"db.ad\", \"yoxdur\"), get(konfiq, \"server.dil.1\"));\nconsole.log(JSON.stringify(set(konfiq, \"db.host.adres\", \"localhost\")));\n"},
  {"id": "js-16-4", "lang": "javascript", "level": 16, "title": "Tagged template və String.raw", "keywords": ["tagged template", "etiketli şablon", "string.raw", "template tag", "шаблонные строки", "html escape", "tag function"], "code": "function vurgula(parcalar, ...deyerler) {\n  return parcalar.reduce((s, p, i) => s + p + (i < deyerler.length ? `[${deyerler[i]}]` : \"\"), \"\");\n}\nconst ad = \"Aysel\", bal = 95;\nconsole.log(vurgula`Tələbə ${ad} ${bal} bal topladı.`);\n\nfunction tehlukesiz(parcalar, ...d) {\n  const esc = (s) => String(s).replace(/[&<>\"]/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c]));\n  return parcalar.reduce((s, p, i) => s + p + (i < d.length ? esc(d[i]) : \"\"), \"\");\n}\nconsole.log(tehlukesiz`<p>${\"<b onclick=\\\"x()\\\">qalın</b>\"}</p>`);\nconsole.log(String.raw`C:\\yeni\\fayl.txt`);\n"},
  {"id": "js-16-5", "lang": "javascript", "level": 16, "title": "Object.freeze, getter və dəyişməzlik", "keywords": ["freeze", "immutable", "dəyişməz", "dondur", "object.freeze", "defineproperty", "неизменяемость", "sabit obyekt", "immutability"], "code": "const sabit = Object.freeze({ ad: \"Nibras\", versiya: 1, alt: { x: 1 } });\nsabit.ad = \"Başqa\";        // səssiz uğursuz olur (strict rejimdə xəta)\nsabit.alt.x = 99;          // freeze dayazdır\nconsole.log(sabit.ad, sabit.alt.x, Object.isFrozen(sabit));\n\nfunction derinDondur(o) {\n  Object.values(o).forEach((v) => typeof v === \"object\" && v !== null && derinDondur(v));\n  return Object.freeze(o);\n}\nconst d = derinDondur({ a: { b: { c: 1 } } });\nd.a.b.c = 5;\nconsole.log(d.a.b.c);\n\nconst o = {};\nObject.defineProperty(o, \"id\", { value: 7, writable: false, enumerable: true });\no.id = 8;\nconsole.log(o.id, Object.getOwnPropertyDescriptor(o, \"id\").writable);\n"},
  {"id": "js-17-1", "lang": "javascript", "level": 17, "title": "BFS: ən qısa yol", "keywords": ["bfs", "qraf", "graph", "en qısa yol", "shortest path", "поиск в ширину", "breadth first", "növbə", "queue", "şəbəkə"], "code": "const qraf = {\n  A: [\"B\", \"C\"],\n  B: [\"A\", \"D\", \"E\"],\n  C: [\"A\", \"F\"],\n  D: [\"B\"],\n  E: [\"B\", \"F\"],\n  F: [\"C\", \"E\"],\n};\n\nfunction bfs(bas, son) {\n  const novbe = [[bas]];\n  const gorulen = new Set([bas]);\n  while (novbe.length) {\n    const yol = novbe.shift();\n    const dugum = yol[yol.length - 1];\n    if (dugum === son) return yol;\n    for (const q of qraf[dugum]) {\n      if (!gorulen.has(q)) {\n        gorulen.add(q);\n        novbe.push([...yol, q]);\n      }\n    }\n  }\n  return null;\n}\nconsole.log(bfs(\"A\", \"F\").join(\" -> \"));\nconsole.log(bfs(\"D\", \"F\").join(\" -> \"));\n"},
  {"id": "js-17-2", "lang": "javascript", "level": 17, "title": "DFS və komponentlər", "keywords": ["dfs", "dərinlik axtarışı", "depth first", "bağlı komponent", "connected components", "поиск в глубину", "qraf komponentləri", "ada sayı"], "code": "const qraf = new Map([\n  [1, [2, 3]], [2, [1]], [3, [1]],\n  [4, [5]], [5, [4]],\n  [6, []],\n]);\n\nfunction dfs(bas, gorulen = new Set()) {\n  gorulen.add(bas);\n  for (const q of qraf.get(bas)) if (!gorulen.has(q)) dfs(q, gorulen);\n  return gorulen;\n}\n\nconst hamisi = new Set();\nconst komponentler = [];\nfor (const d of qraf.keys()) {\n  if (hamisi.has(d)) continue;\n  const k = dfs(d);\n  k.forEach((x) => hamisi.add(x));\n  komponentler.push([...k]);\n}\nconsole.log(\"Komponentlər:\", JSON.stringify(komponentler));\n"},
  {"id": "js-17-3", "lang": "javascript", "level": 17, "title": "Dijkstra alqoritmi", "keywords": ["dijkstra", "ən qısa məsafə", "shortest distance", "çəkili qraf", "weighted graph", "алгоритм дейкстры", "yol tapma", "şəhərlər arası məsafə"], "code": "const yollar = {\n  Bakı: { Sumqayıt: 35, Şamaxı: 120 },\n  Sumqayıt: { Bakı: 35, Quba: 130 },\n  Şamaxı: { Bakı: 120, Şəki: 115, Quba: 150 },\n  Quba: { Sumqayıt: 130, Şamaxı: 150 },\n  Şəki: { Şamaxı: 115 },\n};\n\nfunction dijkstra(bas) {\n  const mesafe = Object.fromEntries(Object.keys(yollar).map((k) => [k, Infinity]));\n  mesafe[bas] = 0;\n  const qalan = new Set(Object.keys(yollar));\n  while (qalan.size) {\n    const u = [...qalan].reduce((a, b) => (mesafe[a] <= mesafe[b] ? a : b));\n    qalan.delete(u);\n    for (const [v, c] of Object.entries(yollar[u])) {\n      if (mesafe[u] + c < mesafe[v]) mesafe[v] = mesafe[u] + c;\n    }\n  }\n  return mesafe;\n}\nconsole.log(dijkstra(\"Bakı\"));\n"},
  {"id": "js-17-4", "lang": "javascript", "level": 17, "title": "Yığın (Stack) və Növbə (Queue)", "keywords": ["stack", "queue", "yığın", "növbə", "lifo", "fifo", "стек", "очередь", "data structure", "verilənlər strukturu", "mötərizə yoxlama"], "code": "class Stack {\n  #a = [];\n  push(x) { this.#a.push(x); }\n  pop() { return this.#a.pop(); }\n  get bos() { return this.#a.length === 0; }\n}\n\nfunction motarizeDogrudur(s) {\n  const cutler = { \")\": \"(\", \"]\": \"[\", \"}\": \"{\" };\n  const st = new Stack();\n  for (const h of s) {\n    if (\"([{\".includes(h)) st.push(h);\n    else if (cutler[h] && st.pop() !== cutler[h]) return false;\n  }\n  return st.bos;\n}\nfor (const s of [\"(a[b]{c})\", \"(]\", \"((\", \"{[()]}\"]) console.log(s, motarizeDogrudur(s));\n\nconst novbe = [];\nnovbe.push(\"A\"); novbe.push(\"B\"); novbe.push(\"C\");\nconsole.log(novbe.shift(), novbe.shift(), novbe);\n"},
  {"id": "js-17-5", "lang": "javascript", "level": 17, "title": "Min-heap və prioritet növbəsi", "keywords": ["heap", "min heap", "prioritet növbəsi", "priority queue", "yığın", "куча", "приоритетная очередь", "ağac", "tree", "ən kiçik element"], "code": "class MinHeap {\n  constructor() { this.a = []; }\n  get size() { return this.a.length; }\n  push(x) {\n    const a = this.a;\n    a.push(x);\n    let i = a.length - 1;\n    while (i > 0) {\n      const p = (i - 1) >> 1;\n      if (a[p] <= a[i]) break;\n      [a[p], a[i]] = [a[i], a[p]];\n      i = p;\n    }\n  }\n  pop() {\n    const a = this.a;\n    const ust = a[0];\n    const son = a.pop();\n    if (a.length) {\n      a[0] = son;\n      let i = 0;\n      for (;;) {\n        let m = i;\n        const l = 2 * i + 1, r = l + 1;\n        if (l < a.length && a[l] < a[m]) m = l;\n        if (r < a.length && a[r] < a[m]) m = r;\n        if (m === i) break;\n        [a[m], a[i]] = [a[i], a[m]];\n        i = m;\n      }\n    }\n    return ust;\n  }\n}\n\nconst h = new MinHeap();\n[42, 7, 19, 3, 88, 21].forEach((x) => h.push(x));\nconst cixan = [];\nwhile (h.size) cixan.push(h.pop());\nconsole.log(cixan);\n"},
  {"id": "js-18-1", "lang": "javascript", "level": 18, "title": "Fibonaççi və pillələr (DP)", "keywords": ["dinamik proqramlaşdırma", "dynamic programming", "dp", "pillələr", "climb stairs", "динамическое программирование", "tabulation", "memoization"], "code": "function pilleler(n) {\n  const dp = [1, 1];\n  for (let i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];\n  return dp[n];\n}\nconsole.log(\"10 pillə neçə yolla çıxılır:\", pilleler(10));\nconsole.log(\"40 pillə:\", pilleler(40));\n\nfunction pulDeyisme(pullar, mebleg) {\n  const dp = Array(mebleg + 1).fill(Infinity);\n  dp[0] = 0;\n  for (let m = 1; m <= mebleg; m++) {\n    for (const p of pullar) if (p <= m) dp[m] = Math.min(dp[m], dp[m - p] + 1);\n  }\n  return dp[mebleg] === Infinity ? -1 : dp[mebleg];\n}\nconsole.log(\"63 qəpiyi minimum:\", pulDeyisme([1, 5, 10, 21, 25], 63), \"pulla vermək\");\n"},
  {"id": "js-18-2", "lang": "javascript", "level": 18, "title": "Ən uzun ortaq alt ardıcıllıq", "keywords": ["lcs", "ən uzun ortaq alt ardıcıllıq", "longest common subsequence", "dp matris", "edit distance", "redaktə məsafəsi", "расстояние левенштейна", "mətn oxşarlığı"], "code": "function lcs(a, b) {\n  const dp = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));\n  for (let i = 1; i <= a.length; i++)\n    for (let j = 1; j <= b.length; j++)\n      dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);\n  return dp[a.length][b.length];\n}\nfunction levenshtein(a, b) {\n  const dp = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);\n  for (let j = 0; j <= b.length; j++) dp[0][j] = j;\n  for (let i = 1; i <= a.length; i++)\n    for (let j = 1; j <= b.length; j++)\n      dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));\n  return dp[a.length][b.length];\n}\nconsole.log(lcs(\"ABCBDAB\", \"BDCABA\"));\nconsole.log(levenshtein(\"kitten\", \"sitting\"));\n"},
  {"id": "js-18-3", "lang": "javascript", "level": 18, "title": "Çanta məsələsi (knapsack)", "keywords": ["knapsack", "çanta məsələsi", "0/1 knapsack", "rukzak", "задача о рюкзаке", "optimallaşdırma", "optimization", "dinamik"], "code": "function canta(esyalar, tutum) {\n  const dp = Array(tutum + 1).fill(0);\n  for (const { cekisi, deyer } of esyalar) {\n    for (let w = tutum; w >= cekisi; w--) {\n      dp[w] = Math.max(dp[w], dp[w - cekisi] + deyer);\n    }\n  }\n  return dp[tutum];\n}\n\nconst esyalar = [\n  { ad: \"noutbuk\", cekisi: 3, deyer: 40 },\n  { ad: \"kitab\", cekisi: 1, deyer: 10 },\n  { ad: \"kamera\", cekisi: 2, deyer: 25 },\n  { ad: \"su\", cekisi: 1, deyer: 5 },\n];\nconsole.log(\"Maksimum dəyər (tutum 4):\", canta(esyalar, 4));\nconsole.log(\"Maksimum dəyər (tutum 6):\", canta(esyalar, 6));\n"},
  {"id": "js-18-4", "lang": "javascript", "level": 18, "title": "Backtracking: permutasiya və alt çoxluqlar", "keywords": ["backtracking", "permutasiya", "permutation", "alt çoxluq", "subsets", "kombinasiya", "перестановки", "geri qayıtma", "combinations"], "code": "function permutasiyalar(arr) {\n  if (arr.length <= 1) return [arr];\n  return arr.flatMap((x, i) =>\n    permutasiyalar([...arr.slice(0, i), ...arr.slice(i + 1)]).map((p) => [x, ...p]),\n  );\n}\nconsole.log(permutasiyalar([1, 2, 3]).map((p) => p.join(\"\")).join(\" \"));\n\nfunction altCoxluqlar(arr) {\n  const net = [];\n  (function qur(i, cari) {\n    if (i === arr.length) return net.push([...cari]);\n    qur(i + 1, cari);\n    cari.push(arr[i]);\n    qur(i + 1, cari);\n    cari.pop();\n  })(0, []);\n  return net;\n}\nconsole.log(altCoxluqlar([\"a\", \"b\", \"c\"]).map((s) => `{${s.join(\",\")}}`).join(\" \"));\n"},
  {"id": "js-18-5", "lang": "javascript", "level": 18, "title": "N vəzir məsələsi", "keywords": ["n queens", "n vəzir", "vəzir məsələsi", "şahmat", "ферзи", "ферзи", "backtracking", "lövhə"], "code": "function vezirler(n) {\n  let say = 0;\n  const sutun = new Set(), d1 = new Set(), d2 = new Set();\n  (function qoy(s) {\n    if (s === n) return say++;\n    for (let c = 0; c < n; c++) {\n      if (sutun.has(c) || d1.has(s - c) || d2.has(s + c)) continue;\n      sutun.add(c); d1.add(s - c); d2.add(s + c);\n      qoy(s + 1);\n      sutun.delete(c); d1.delete(s - c); d2.delete(s + c);\n    }\n  })(0);\n  return say;\n}\nfor (const n of [4, 5, 6, 8]) console.log(`${n} vəzir: ${vezirler(n)} həll`);\n"},
  {"id": "js-19-1", "lang": "javascript", "level": 19, "title": "Promise və setTimeout", "keywords": ["promise", "settimeout", "asinxron", "async", "callback", "обещание", "söz", "gözləmək", "sleep", "промис", "gecikmə"], "code": "const gozle = (ms, deyer) => new Promise((hell) => setTimeout(() => hell(deyer), ms));\n\nconsole.log(\"1. Başladı\");\ngozle(30, \"3. 30ms sonra\").then(console.log);\ngozle(10, \"2. 10ms sonra\").then(console.log);\nconsole.log(\"1b. Sinxron kod əvvəl bitir\");\n"},
  {"id": "js-19-2", "lang": "javascript", "level": 19, "title": "async / await", "keywords": ["async await", "asinxron funksiya", "await", "promise", "async function", "асинхронная функция", "gözlə", "ardıcıl icra", "try catch async"], "code": "const gozle = (ms) => new Promise((r) => setTimeout(r, ms));\n\nasync function melumatGetir(id) {\n  await gozle(10);\n  if (id < 0) throw new Error(\"Yanlış id: \" + id);\n  return { id, ad: \"İstifadəçi \" + id };\n}\n\nasync function esas() {\n  const a = await melumatGetir(1);\n  console.log(a);\n  try {\n    await melumatGetir(-1);\n  } catch (e) {\n    console.log(\"Tutuldu:\", e.message);\n  }\n  console.log(\"Bitdi\");\n}\nesas();\n"},
  {"id": "js-19-3", "lang": "javascript", "level": 19, "title": "Promise.all, race, allSettled", "keywords": ["promise.all", "promise.race", "allsettled", "paralel", "parallel promises", "одновременные запросы", "eyni anda", "bir neçə promise"], "code": "const task = (ad, ms, ugur = true) =>\n  new Promise((hell, redd) => setTimeout(() => (ugur ? hell(ad) : redd(new Error(ad + \" uğursuz\"))), ms));\n\n(async () => {\n  console.log(await Promise.all([task(\"A\", 30), task(\"B\", 10), task(\"C\", 20)]));\n  console.log(await Promise.race([task(\"yavaş\", 40), task(\"sürətli\", 5)]));\n  const r = await Promise.allSettled([task(\"ok\", 5), task(\"pis\", 5, false)]);\n  console.log(r.map((x) => x.status + \":\" + (x.value || x.reason.message)));\n  console.log(await Promise.any([task(\"x\", 20, false), task(\"y\", 10)]));\n})();\n"},
  {"id": "js-19-4", "lang": "javascript", "level": 19, "title": "Sadə EventEmitter", "keywords": ["eventemitter", "hadisə", "event", "on emit", "observer", "наблюдатель", "событие", "publish subscribe", "pub/sub", "hadisə sistemi"], "code": "class Emitter {\n  #h = new Map();\n  on(ad, f) {\n    if (!this.#h.has(ad)) this.#h.set(ad, []);\n    this.#h.get(ad).push(f);\n    return () => this.off(ad, f);\n  }\n  off(ad, f) {\n    this.#h.set(ad, (this.#h.get(ad) || []).filter((x) => x !== f));\n  }\n  emit(ad, ...args) {\n    (this.#h.get(ad) || []).forEach((f) => f(...args));\n  }\n}\n\nconst e = new Emitter();\nconst dayan = e.on(\"mesaj\", (m) => console.log(\"1-ci dinləyici:\", m));\ne.on(\"mesaj\", (m) => console.log(\"2-ci dinləyici:\", m.toUpperCase()));\ne.emit(\"mesaj\", \"salam\");\ndayan();\ne.emit(\"mesaj\", \"ikinci\");\n"},
  {"id": "js-19-5", "lang": "javascript", "level": 19, "title": "Növbə ilə eyni anda məhdud işlər", "keywords": ["konkurensiya", "concurrency", "limit", "iş növbəsi", "task pool", "pool", "ограничение параллельности", "retry", "təkrar cəhd", "timeout"], "code": "const gozle = (ms) => new Promise((r) => setTimeout(r, ms));\n\nasync function limitli(isler, limit) {\n  const netice = [];\n  let indeks = 0, aktiv = 0, maxAktiv = 0;\n  async function isci() {\n    while (indeks < isler.length) {\n      const i = indeks++;\n      aktiv++;\n      maxAktiv = Math.max(maxAktiv, aktiv);\n      netice[i] = await isler[i]();\n      aktiv--;\n    }\n  }\n  await Promise.all(Array.from({ length: limit }, isci));\n  return { netice, maxAktiv };\n}\n\nconst isler = [1, 2, 3, 4, 5, 6].map((n) => async () => { await gozle(10 * n); return n * n; });\nlimitli(isler, 2).then((r) => console.log(r));\n\nasync function tekrar(f, say) {\n  for (let i = 1; i <= say; i++) {\n    try { return await f(i); } catch (e) { console.log(`Cəhd ${i} uğursuz`); }\n  }\n  return \"hamısı uğursuz\";\n}\ntekrar(async (i) => { if (i < 3) throw new Error(\"x\"); return \"3-cü cəhd uğurlu\"; }, 5).then(console.log);\n"},
  {"id": "js-20-1", "lang": "javascript", "level": 20, "title": "Bank hesabı simulyasiyası", "keywords": ["bank", "hesab", "bank hesabı", "mini layihə", "mini project", "банк", "əməliyyatlar", "depozit", "köçürmə", "transaction", "tətbiq"], "code": "class BankHesabi {\n  #balans = 0;\n  #tarixce = [];\n  constructor(sahib, baslangic = 0) {\n    this.sahib = sahib;\n    if (baslangic) this.yatir(baslangic);\n  }\n  yatir(m) {\n    if (m <= 0) throw new Error(\"Məbləğ müsbət olmalıdır\");\n    this.#balans += m;\n    this.#tarixce.push(`+${m}`);\n  }\n  cixar(m) {\n    if (m > this.#balans) throw new Error(\"Balans kifayət etmir\");\n    this.#balans -= m;\n    this.#tarixce.push(`-${m}`);\n  }\n  get balans() { return this.#balans; }\n  get tarixce() { return [...this.#tarixce]; }\n}\nfunction kocur(a, b, m) { a.cixar(m); b.yatir(m); }\n\nconst a = new BankHesabi(\"Aysel\", 500), b = new BankHesabi(\"Murad\");\nkocur(a, b, 200);\ntry { kocur(b, a, 1000); } catch (e) { console.log(\"Xəta:\", e.message); }\nconsole.log(a.sahib, a.balans, a.tarixce);\nconsole.log(b.sahib, b.balans, b.tarixce);\n"},
  {"id": "js-20-2", "lang": "javascript", "level": 20, "title": "XO oyunu məntiqi", "keywords": ["xo", "tic tac toe", "xo oyunu", "oyun", "game", "крестики-нолики", "üç daş", "lövhə oyunu", "qalib yoxla", "minimax"], "code": "const xetler = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];\nconst qalib = (t) => {\n  for (const [a, b, c] of xetler) if (t[a] && t[a] === t[b] && t[a] === t[c]) return t[a];\n  return t.every(Boolean) ? \"berabere\" : null;\n};\n\nfunction minimax(t, oyuncu) {\n  const q = qalib(t);\n  if (q) return { skor: q === \"O\" ? 1 : q === \"X\" ? -1 : 0 };\n  let en = { skor: oyuncu === \"O\" ? -2 : 2 };\n  t.forEach((h, i) => {\n    if (h) return;\n    t[i] = oyuncu;\n    const s = minimax(t, oyuncu === \"O\" ? \"X\" : \"O\").skor;\n    t[i] = null;\n    if (oyuncu === \"O\" ? s > en.skor : s < en.skor) en = { skor: s, i };\n  });\n  return en;\n}\n\nconst tax = [\"X\", \"X\", null, null, \"O\", null, null, null, null];\nconst hereket = minimax(tax, \"O\");\nconsole.log(\"Kompüterin hərəkəti (O):\", hereket.i);\ntax[hereket.i] = \"O\";\nconsole.log(tax.map((x) => x || \"_\").join(\"\"));\n"},
  {"id": "js-20-3", "lang": "javascript", "level": 20, "title": "Riyazi ifadə hesablayıcı (parser)", "keywords": ["parser", "kalkulyator", "ifadə hesabla", "expression parser", "tokenizer", "калькулятор", "riyazi ifadə", "2+3*4", "shunting yard", "evaluate"], "code": "function hesabla(ifade) {\n  const tok = ifade.match(/\\d+\\.?\\d*|[()+\\-*/^]/g);\n  let p = 0;\n  const bax = () => tok[p], al = () => tok[p++];\n  function ifadeP() {\n    let s = termP();\n    while (bax() === \"+\" || bax() === \"-\") s = al() === \"+\" ? s + termP() : s - termP();\n    return s;\n  }\n  function termP() {\n    let s = quvvetP();\n    while (bax() === \"*\" || bax() === \"/\") s = al() === \"*\" ? s * quvvetP() : s / quvvetP();\n    return s;\n  }\n  function quvvetP() {\n    const b = atomP();\n    return bax() === \"^\" ? (al(), b ** quvvetP()) : b;\n  }\n  function atomP() {\n    const t = al();\n    if (t === \"(\") { const v = ifadeP(); al(); return v; }\n    if (t === \"-\") return -atomP();\n    return Number(t);\n  }\n  return ifadeP();\n}\nfor (const e of [\"2+3*4\", \"(2+3)*4\", \"2^3^2\", \"10/4-1\", \"-(3+2)*2\"]) console.log(e, \"=\", hesabla(e));\n"},
  {"id": "js-20-4", "lang": "javascript", "level": 20, "title": "LRU keş", "keywords": ["lru cache", "keş", "cache", "yaddaş keşi", "kэш lru", "ən az istifadə edilən", "mini layihə", "map ilə keş", "data structure"], "code": "class LRU {\n  #max; #m = new Map();\n  constructor(max) { this.#max = max; }\n  get(k) {\n    if (!this.#m.has(k)) return undefined;\n    const v = this.#m.get(k);\n    this.#m.delete(k);\n    this.#m.set(k, v);\n    return v;\n  }\n  set(k, v) {\n    this.#m.delete(k);\n    this.#m.set(k, v);\n    if (this.#m.size > this.#max) this.#m.delete(this.#m.keys().next().value);\n  }\n  get acarlar() { return [...this.#m.keys()]; }\n}\n\nconst kes = new LRU(3);\nkes.set(\"a\", 1); kes.set(\"b\", 2); kes.set(\"c\", 3);\nkes.get(\"a\");\nkes.set(\"d\", 4);   // ən az istifadə olunan \"b\" silinir\nconsole.log(kes.acarlar, kes.get(\"b\"));\n"},
  {"id": "js-20-5", "lang": "javascript", "level": 20, "title": "Alış-veriş səbəti", "keywords": ["alış-veriş səbəti", "shopping cart", "səbət", "sebet", "корзина", "mağaza", "endirim", "kupon", "hesab-faktura", "mini layihə"], "code": "class Sebet {\n  #setirler = new Map();\n  elave(ad, qiymet, say = 1) {\n    const s = this.#setirler.get(ad) || { qiymet, say: 0 };\n    s.say += say;\n    this.#setirler.set(ad, s);\n    return this;\n  }\n  sil(ad) { this.#setirler.delete(ad); return this; }\n  cem(endirimFaiz = 0) {\n    let t = 0;\n    for (const { qiymet, say } of this.#setirler.values()) t += qiymet * say;\n    return +(t * (1 - endirimFaiz / 100)).toFixed(2);\n  }\n  qebz() {\n    return [...this.#setirler].map(([ad, { qiymet, say }]) => `${ad.padEnd(8)} ${say} x ${qiymet.toFixed(2)} = ${(say * qiymet).toFixed(2)}`).join(\"\\n\");\n  }\n}\n\nconst s = new Sebet().elave(\"Kitab\", 12.5, 2).elave(\"Qələm\", 1.2, 10).elave(\"Çanta\", 35);\nconsole.log(s.qebz());\nconsole.log(\"Cəmi:\", s.cem(), \"| 10% endirimlə:\", s.cem(10));\n"},
];
